owl:Class rdfs:subClassOf rdfs:Class .

owl:DatatypeProperty rdfs:subClassOf rdf:Property .

calidad:ConfirmadaPorPersona a sh:NodeShape ;
    rdfs:label "Cada decisión sobre un candidato dudoso la confirmó una persona (informativa)" ;
    rdfs:comment "Las decisiones las tomó un asistente de IA y las validó otro. Quién decidió y si una persona confirmó son dos datos distintos; esta regla no bloquea las respuestas." ;
    sh:property [ sh:message "Decidido por un asistente de IA; falta que una persona lo confirme." ;
            sh:minCount 1 ;
            sh:not [ sh:in ( "pending" ) ] ;
            sh:path afiliaciones:humanConfirmation ;
            sh:severity sh:Info ] ;
    sh:targetClass afiliaciones:DoubtfulCandidate .

@prefix afiliaciones: <https://w3id.org/rastro/afiliaciones#> .
@prefix calidad: <https://w3id.org/rastro/afiliaciones/calidad#> .
