owl:Class rdfs:subClassOf rdfs:Class .

owl:DatatypeProperty rdfs:subClassOf rdf:Property .

calidad:DudosaDecidida a sh:NodeShape ;
    rdfs:label "Cada candidato dudoso tiene una decisión, aceptar o rechazar, y su motivo" ;
    rdfs:comment "Sin decisión, un candidato no se sabe si cuenta; sin motivo, no se puede revisar por qué se aceptó o rechazó." ;
    sh:property [ sh:in ( "accept" "reject" ) ;
            sh:maxCount 1 ;
            sh:message "No tiene una decisión, aceptar o rechazar." ;
            sh:minCount 1 ;
            sh:path afiliaciones:reviewDecision ],
        [ sh:message "No dice el motivo de la decisión." ;
            sh:minCount 1 ;
            sh:minLength 1 ;
            sh:path afiliaciones:decisionReason ] ;
    sh:targetClass afiliaciones:DoubtfulCandidate .

