owl:Class rdfs:subClassOf rdfs:Class .

owl:DatatypeProperty rdfs:subClassOf rdf:Property .

calidad:IdentificacionCompleta a sh:NodeShape ;
    rdfs:label "Cada identificación dice qué mención, qué organización, con qué regla y evidencia, y de qué dos fuentes sale" ;
    rdfs:comment "Las identificaciones son lo que Rastro cuenta. Sin su mención, su organización, su regla, su evidencia o alguna de sus dos fuentes (Crossref y ROR), no se pueden auditar." ;
    sh:property [ sh:maxCount 1 ;
            sh:message "No es de una sola mención." ;
            sh:minCount 1 ;
            sh:path afiliaciones:ofMention ],
        [ sh:maxCount 1 ;
            sh:message "No identifica una sola organización." ;
            sh:minCount 1 ;
            sh:path afiliaciones:identifies ],
        [ sh:message "No dice con qué regla se identificó." ;
            sh:minCount 1 ;
            sh:path afiliaciones:rule ],
        [ sh:message "No tiene evidencia." ;
            sh:minCount 1 ;
            sh:minLength 1 ;
            sh:path afiliaciones:sourceText ],
        [ sh:hasValue fuente:crossref ;
            sh:message "No dice que sale de Crossref." ;
            sh:path prov:wasDerivedFrom ],
        [ sh:hasValue fuente:ror ;
            sh:message "No dice que sale de ROR." ;
            sh:path prov:wasDerivedFrom ] ;
    sh:targetClass afiliaciones:Identification .

