reglas.shacl:
@prefix afiliaciones: <https://w3id.org/rastro/afiliaciones#> .
@prefix calidad: <https://w3id.org/rastro/afiliaciones/calidad#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

owl:Class rdfs:subClassOf rdfs:Class .

owl:DatatypeProperty rdfs:subClassOf rdf:Property .

calidad:PublicacionConDoi a sh:NodeShape ;
    rdfs:label "Cada publicación tiene un solo DOI, con su formato" ;
    rdfs:comment "Por el DOI se identifica la publicación en Crossref y se cuenta una sola vez por organización." ;
    sh:property [ sh:maxCount 1 ;
            sh:message "No tiene un DOI, tiene más de uno, o uno con otro formato." ;
            sh:minCount 1 ;
            sh:path afiliaciones:doi ;
            sh:pattern "^10\\.[0-9]+(\\.[0-9]+)*/\\S+$" ] ;
    sh:targetClass afiliaciones:Publication .

@prefix afiliaciones: <https://w3id.org/rastro/afiliaciones#> .
@prefix calidad: <https://w3id.org/rastro/afiliaciones/calidad#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

owl:Class rdfs:subClassOf rdfs:Class .

owl:DatatypeProperty rdfs:subClassOf rdf:Property .

calidad:RegistroActivo a sh:NodeShape ;
    rdfs:label "Cada organización identificada está activa en ROR v2.15 (aviso para revisar)" ;
    rdfs:comment "Un registro retirado o inactivo en ROR no hace falsa la afiliación: la publicación la nombra. Es un aviso para que una persona decida si la mantiene o suma la sucesora; la regla no la cambia." ;
    sh:sparql [ sh:message "El registro figura como «{?status}» en ROR v2.15; sucesora en ROR: {?successorName}. La identificación no cambia: una persona decide." ;
            sh:select """
            SELECT $this (MIN(?s) AS ?status) (COALESCE(MIN(?n), "ninguna") AS ?successorName) WHERE {
                $this <https://w3id.org/rastro/afiliaciones#status> ?s .
                FILTER (?s != "active")
                OPTIONAL { $this <https://w3id.org/rastro/afiliaciones#successor> ?x .
                           ?x <https://w3id.org/rastro/afiliaciones#name> ?n }
            } GROUP BY $this HAVING (COUNT(?s) > 0)
        """ ;
            sh:severity sh:Warning ] ;
    sh:targetObjectsOf afiliaciones:identifies .

